WHERE c.course_code = 'HS7-ESP' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Talento at Kakayahan', m.description = 'Ang likas na galing, ang galing na nalilinang, at kung paano ito pauunlarin.', m.content = '<p>Bawat tao ay may natatanging galing. May magaling kumanta, may magaling sa numero, at may mahusay makisama. Ang hamon ay tuklasin ang galing na ito at paunlarin upang magamit sa sarili at sa kapwa.</p><p>Sa modyul na ito, pag-aaralan mo ang pagkakaiba ng talento at kakayahan at kung paano ito mapauunlad.</p><h3>Mahahalagang konsepto</h3><ul><li><strong>Talento</strong>: Ang talento ay likas na galing o regalo na mayroon ang isang tao mula pa pagkabata, gaya ng magandang boses o galing sa pagguhit. Gayunman, kahit likas ito, kailangan pa rin itong linangin upang hindi mawala.</li><li><strong>Kakayahan</strong>: Ang kakayahan ay galing na natutunan at napaunlad sa pamamagitan ng pagsasanay at pag-aaral, gaya ng pagluluto, pagta-type, o pagtugtog ng gitara. Halos lahat ng kakayahan ay maaaring matutunan kung may tiyaga.</li><li><strong>Tiwala sa sarili</strong>: Ito ay paniniwala na kaya mong gawin ang isang bagay. Ito ang nagtutulak sa tao na subukan ang bagong gawain at hindi sumuko kapag nagkamali.</li></ul><h3>Mga uri ng talino</h3><p>Ayon kay Howard Gardner, hindi iisa ang uri ng talino. Ilan sa mga ito ay:</p><ul><li><strong>Linguistic</strong>: Galing sa salita, pagbasa, at pagsulat.</li><li><strong>Logical-Mathematical</strong>: Galing sa numero at lohikal na pag-iisip.</li><li><strong>Musical</strong>: Galing sa musika, ritmo, at himig.</li><li><strong>Bodily-Kinesthetic</strong>: Galing sa paggamit ng katawan, gaya ng sayaw at isports.</li><li><strong>Interpersonal</strong>: Galing sa pakikisama at pag-unawa sa ibang tao.</li></ul><p>Ipinapakita nito na matalino ang bawat isa sa sariling paraan.</p><h3>Paano paunlarin ang talento at kakayahan</h3><ul><li>Magsanay nang regular, kahit kaunti araw-araw.</li><li>Humanap ng guro o halimbawang matututunan.</li><li>Tanggapin ang puna bilang tulong, hindi bilang pang-iinsulto.</li><li>Gamitin ang galing sa paglilingkod sa pamilya, paaralan, at komunidad.</li></ul><h3>Talento laban sa kakayahan</h3><table><thead><tr><th></th><th>Talento</th><th>Kakayahan</th></tr></thead><tbody><tr><td>Pinagmulan</td><td>Likas o regalo</td><td>Natutunan sa pagsasanay</td></tr><tr><td>Halimbawa</td><td>Magandang boses</td><td>Pagtugtog ng gitara</td></tr><tr><td>Kailangan ba ng pagsasanay?</td><td>Oo, upang lumago</td><td>Oo, upang matutunan</td></tr></tbody></table><h3>Pagsusulit</h3><ol><li>Ano ang pagkakaiba ng talento at kakayahan?</li><li>Sino ang nagpaliwanag ng iba''t ibang uri ng talino?</li><li>Paano magagamit ang talento sa paglilingkod sa kapwa?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Ang talento ay likas; ang kakayahan ay natutunan sa pagsasanay.</li><li>Howard Gardner</li><li>Halimbawa: pagtuturo sa kaklase, pagtulong sa proyekto ng paaralan o barangay.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS7-ESP' AND m.module_number = 2 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 2, 'Talento at Kakayahan', 'Ang likas na galing, ang galing na nalilinang, at kung paano ito pauunlarin.', '<p>Bawat tao ay may natatanging galing. May magaling kumanta, may magaling sa numero, at may mahusay makisama. Ang hamon ay tuklasin ang galing na ito at paunlarin upang magamit sa sarili at sa kapwa.</p><p>Sa modyul na ito, pag-aaralan mo ang pagkakaiba ng talento at kakayahan at kung paano ito mapauunlad.</p><h3>Mahahalagang konsepto</h3><ul><li><strong>Talento</strong>: Ang talento ay likas na galing o regalo na mayroon ang isang tao mula pa pagkabata, gaya ng magandang boses o galing sa pagguhit. Gayunman, kahit likas ito, kailangan pa rin itong linangin upang hindi mawala.</li><li><strong>Kakayahan</strong>: Ang kakayahan ay galing na natutunan at napaunlad sa pamamagitan ng pagsasanay at pag-aaral, gaya ng pagluluto, pagta-type, o pagtugtog ng gitara. Halos lahat ng kakayahan ay maaaring matutunan kung may tiyaga.</li><li><strong>Tiwala sa sarili</strong>: Ito ay paniniwala na kaya mong gawin ang isang bagay. Ito ang nagtutulak sa tao na subukan ang bagong gawain at hindi sumuko kapag nagkamali.</li></ul><h3>Mga uri ng talino</h3><p>Ayon kay Howard Gardner, hindi iisa ang uri ng talino. Ilan sa mga ito ay:</p><ul><li><strong>Linguistic</strong>: Galing sa salita, pagbasa, at pagsulat.</li><li><strong>Logical-Mathematical</strong>: Galing sa numero at lohikal na pag-iisip.</li><li><strong>Musical</strong>: Galing sa musika, ritmo, at himig.</li><li><strong>Bodily-Kinesthetic</strong>: Galing sa paggamit ng katawan, gaya ng sayaw at isports.</li><li><strong>Interpersonal</strong>: Galing sa pakikisama at pag-unawa sa ibang tao.</li></ul><p>Ipinapakita nito na matalino ang bawat isa sa sariling paraan.</p><h3>Paano paunlarin ang talento at kakayahan</h3><ul><li>Magsanay nang regular, kahit kaunti araw-araw.</li><li>Humanap ng guro o halimbawang matututunan.</li><li>Tanggapin ang puna bilang tulong, hindi bilang pang-iinsulto.</li><li>Gamitin ang galing sa paglilingkod sa pamilya, paaralan, at komunidad.</li></ul><h3>Talento laban sa kakayahan</h3><table><thead><tr><th></th><th>Talento</th><th>Kakayahan</th></tr></thead><tbody><tr><td>Pinagmulan</td><td>Likas o regalo</td><td>Natutunan sa pagsasanay</td></tr><tr><td>Halimbawa</td><td>Magandang boses</td><td>Pagtugtog ng gitara</td></tr><tr><td>Kailangan ba ng pagsasanay?</td><td>Oo, upang lumago</td><td>Oo, upang matutunan</td></tr></tbody></table><h3>Pagsusulit</h3><ol><li>Ano ang pagkakaiba ng talento at kakayahan?</li><li>Sino ang nagpaliwanag ng iba''t ibang uri ng talino?</li><li>Paano magagamit ang talento sa paglilingkod sa kapwa?</li></ol><details><summary>Ipakita ang sagot</summary><ol><li>Ang talento ay likas; ang kakayahan ay natutunan sa pagsasanay.</li><li>Howard Gardner</li><li>Halimbawa: pagtuturo sa kaklase, pagtulong sa proyekto ng paaralan o barangay.</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS7-ESP' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 2);

-- HS7-MAPEH
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Music of the Philippine Lowlands', m.description = 'Folk songs, musical forms, and instruments of lowland communities.', m.content = '<p>The lowland areas of Luzon and the Visayas are home to music that blends native traditions with Spanish influences. This music is heard in fiestas, church celebrations, and everyday life, and many of its songs are still sung in schools today.</p><p>In this module, you will learn the common forms of lowland music, its instruments, and the basic musical elements found in folk songs.</p><h3>Forms of lowland music</h3><ul><li><strong>Folk song</strong>: A folk song is a simple traditional song about daily life, work, love, or nature. Folk songs are usually easy to sing and are passed down by ear. "Bahay Kubo" lists vegetables found around a nipa hut, while "Leron Leron Sinta" describes climbing a papaya tree.</li><li><strong>Kundiman</strong>: The kundiman is a Filipino love song that is slow and emotional. It usually starts in a minor key and may shift to a major key. During the Spanish and American periods, some kundiman hid messages of love for the country.</li><li><strong>Harana</strong>: The harana is a serenade sung by a young man outside the house of the woman he courts, often with a guitar. It shows respect and sincerity in traditional Filipino courtship.</li><li><strong>Religious music</strong>: Spanish colonization introduced church music. The pasyon, a chanted story of the life and death of Jesus, is sung during Holy Week in many lowland communities.</li></ul><h3>Lowland instruments</h3><ul><li><strong>Rondalla</strong>: The rondalla is an ensemble of plucked string instruments such as the bandurria, octavina, laud, guitar, and bass. It often plays at fiestas and cultural shows.</li><li><strong>Bandurria</strong>: The bandurria is a small, pear-shaped string instrument that usually plays the melody in a rondalla.</li><li><strong>Banda</strong>: A brass band, or banda, plays during town fiestas and processions.</li></ul><h3>Elements of folk songs</h3><ul><li><strong>Meter</strong>: Meter is the pattern of strong and weak beats. Many folk songs are in 2/4 or 3/4 time. A song in 3/4 time, like a waltz, has a strong beat followed by two weak beats.</li><li><strong>Melody</strong>: Melody is the tune of the song, the series of notes you remember and hum.</li><li><strong>Mood</strong>: Mood is the feeling the song creates. Bahay Kubo is cheerful, while many kundiman are sad and longing.</li></ul><h3>Summary of lowland music</h3><table><thead><tr><th>Form or instrument</th><th>Description</th><th>Example or use</th></tr></thead><tbody><tr><td>Folk song</td><td>Simple song about daily life</td><td>Bahay Kubo</td></tr><tr><td>Kundiman</td><td>Slow, emotional love song</td><td>Sung in recitals and programs</td></tr><tr><td>Harana</td><td>Serenade during courtship</td><td>Sung with a guitar</td></tr><tr><td>Rondalla</td><td>Plucked string ensemble</td><td>Fiestas and cultural shows</td></tr></tbody></table><h3>Quick check</h3><ol><li>What is a kundiman?</li><li>Which instrument usually plays the melody in a rondalla?</li><li>How many beats per measure does a song in 3/4 time have?</li></ol><details><summary>Show answers</summary><ol><li>A slow, emotional Filipino love song.</li><li>Bandurria</li><li>Three</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS7-MAPEH' AND m.module_number = 1 AND m.updated_by IS NULL;
INSERT INTO modules (course_id, module_number, title, description, content, published)
SELECT c.id, 1, 'Music of the Philippine Lowlands', 'Folk songs, musical forms, and instruments of lowland communities.', '<p>The lowland areas of Luzon and the Visayas are home to music that blends native traditions with Spanish influences. This music is heard in fiestas, church celebrations, and everyday life, and many of its songs are still sung in schools today.</p><p>In this module, you will learn the common forms of lowland music, its instruments, and the basic musical elements found in folk songs.</p><h3>Forms of lowland music</h3><ul><li><strong>Folk song</strong>: A folk song is a simple traditional song about daily life, work, love, or nature. Folk songs are usually easy to sing and are passed down by ear. "Bahay Kubo" lists vegetables found around a nipa hut, while "Leron Leron Sinta" describes climbing a papaya tree.</li><li><strong>Kundiman</strong>: The kundiman is a Filipino love song that is slow and emotional. It usually starts in a minor key and may shift to a major key. During the Spanish and American periods, some kundiman hid messages of love for the country.</li><li><strong>Harana</strong>: The harana is a serenade sung by a young man outside the house of the woman he courts, often with a guitar. It shows respect and sincerity in traditional Filipino courtship.</li><li><strong>Religious music</strong>: Spanish colonization introduced church music. The pasyon, a chanted story of the life and death of Jesus, is sung during Holy Week in many lowland communities.</li></ul><h3>Lowland instruments</h3><ul><li><strong>Rondalla</strong>: The rondalla is an ensemble of plucked string instruments such as the bandurria, octavina, laud, guitar, and bass. It often plays at fiestas and cultural shows.</li><li><strong>Bandurria</strong>: The bandurria is a small, pear-shaped string instrument that usually plays the melody in a rondalla.</li><li><strong>Banda</strong>: A brass band, or banda, plays during town fiestas and processions.</li></ul><h3>Elements of folk songs</h3><ul><li><strong>Meter</strong>: Meter is the pattern of strong and weak beats. Many folk songs are in 2/4 or 3/4 time. A song in 3/4 time, like a waltz, has a strong beat followed by two weak beats.</li><li><strong>Melody</strong>: Melody is the tune of the song, the series of notes you remember and hum.</li><li><strong>Mood</strong>: Mood is the feeling the song creates. Bahay Kubo is cheerful, while many kundiman are sad and longing.</li></ul><h3>Summary of lowland music</h3><table><thead><tr><th>Form or instrument</th><th>Description</th><th>Example or use</th></tr></thead><tbody><tr><td>Folk song</td><td>Simple song about daily life</td><td>Bahay Kubo</td></tr><tr><td>Kundiman</td><td>Slow, emotional love song</td><td>Sung in recitals and programs</td></tr><tr><td>Harana</td><td>Serenade during courtship</td><td>Sung with a guitar</td></tr><tr><td>Rondalla</td><td>Plucked string ensemble</td><td>Fiestas and cultural shows</td></tr></tbody></table><h3>Quick check</h3><ol><li>What is a kundiman?</li><li>Which instrument usually plays the melody in a rondalla?</li><li>How many beats per measure does a song in 3/4 time have?</li></ol><details><summary>Show answers</summary><ol><li>A slow, emotional Filipino love song.</li><li>Bandurria</li><li>Three</li></ol></details>', 1 FROM courses c
WHERE c.course_code = 'HS7-MAPEH' AND NOT EXISTS (SELECT 1 FROM modules x WHERE x.course_id = c.id AND x.module_number = 1);
UPDATE modules m JOIN courses c ON c.id = m.course_id
SET m.title = 'Arts and Crafts of the Philippine Lowlands', m.description = 'Traditional crafts made from local materials and the elements of design they use.', m.content = '<p>Lowland Filipinos have long turned local materials such as clay, wood, fibers, and shells into useful and beautiful objects. These crafts show both the creativity of the people and the resources available in their communities.</p><p>In this module, you will learn about common lowland crafts, where they come from, and the art elements used in their designs.</p><h3>Common lowland crafts</h3><ul><li><strong>Weaving</strong>: Weaving is making cloth or mats by crossing threads or strips over and under each other. Ilocos is known for inabel, a handwoven cloth with bold patterns, while many provinces weave banig, sleeping mats made from leaves.</li><li><strong>Pottery</strong>: Pottery is shaping clay into jars, pots, and other objects, then hardening them with heat. Vigan in Ilocos Sur is known for burnay, sturdy brown jars used to store water, rice, and fermented fish.</li><li><strong>Wood carving</strong>: Wood carving is shaping wood into figures and designs using knives and chisels. Paete in Laguna is famous for its skilled carvers, who make religious images, furniture, and decorations.</li><li><strong>Papier-mâché</strong>: Papier-mâché is a craft that shapes paper and paste into objects. Paete also produces taka, colorful papier-mâché figures, often in the shape of horses.</li></ul><h3>Elements of art in crafts</h3><ul><li><strong>Line</strong>: Lines create borders and shapes in woven patterns and carvings.</li><li><strong>Shape</strong>: Shapes such as diamonds, squares, and flowers are repeated in many designs.</li><li><strong>Color</strong>: Natural dyes from plants were traditionally used, giving earthy reds, browns, and blues.</li><li><strong>Texture</strong>: Texture is how a surface feels or looks like it would feel, such as the rough weave of a mat or the smooth surface of a carved figure.</li></ul><h3>Principles of design</h3><ul><li><strong>Pattern</strong>: A pattern is a design that repeats. Patterns are found in woven cloth, mats, and borders of pots.</li><li><strong>Balance</strong>: Balance is the even distribution of elements so the design looks stable. Many lowland designs use symmetry, where both sides are the same.</li><li><strong>Rhythm</strong>: Rhythm is the sense of movement created by repeating elements, guiding the eye across the design.</li></ul><h3>Crafts and their origins</h3><table><thead><tr><th>Craft</th><th>Place known for it</th><th>Material</th></tr></thead><tbody><tr><td>Inabel weaving</td><td>Ilocos</td><td>Cotton thread</td></tr><tr><td>Burnay jars</td><td>Vigan, Ilocos Sur</td><td>Clay</td></tr><tr><td>Wood carving</td><td>Paete, Laguna</td><td>Wood</td></tr><tr><td>Taka</td><td>Paete, Laguna</td><td>Paper and paste</td></tr></tbody></table><h3>Quick check</h3><ol><li>What is burnay and where is it from?</li><li>What is a pattern in design?</li><li>What does symmetry mean in a design?</li></ol><details><summary>Show answers</summary><ol><li>A brown clay jar from Vigan, Ilocos Sur.</li><li>A design that repeats.</li><li>Both sides of the design are the same.</li></ol></details>', m.published = 1
WHERE c.course_code = 'HS7-MAPEH' AND m.module_number = 2 AND m.updated_by IS NULL;
